insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 16, 17, 'Esta, seguindo após Paulo e nós, clamava, dizendo: Estes homens são servos do Deus Altíssimo, que nos anunciam o caminho da salvação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 16, 18, 'E ela fazia isto por muitos dias. Mas Paulo, estando descontente com isto, virou-se, e disse ao espírito: Em nome de Jesus Cristo eu te mando que saias dela.E na mesma hora [o espírito] saiu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 16, 19, 'E os senhores dela, vendo que a esperança de lucro deles tinha ido embora, pegaram a Paulo e a Silas, e [os] levaram à praça, diante dos governantes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 16, 20, 'E apresentando-os aos magistrados, disseram: Estes homens perturbam nossa cidade, sendo judeus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 16, 21, 'E eles anunciam costumes que não nos é lícito receber, nem fazer; pois somos romanos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 16, 22, 'E a multidão se levantou juntamente contra eles; e os oficiais, rasgando suas roupas, mandaram que fossem açoitados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 16, 23, 'E tendo sido lhes dado muitos açoites, os lançaram na prisão, mandando ao carcereiro que os guardasse em segurança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 16, 24, 'O qual, tendo recebido tal ordem, lançou-os na cela mais interna, e prendeu-lhes os pés no tronco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 16, 25, 'E perto da meia-noite, Paulo e Silas [estavam] orando, e cantando hinos a Deus; [e] os [outros] presos os escutavam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 16, 26, 'E de repente houve um terremoto tão grande que os alicerces da prisão se moviam; e logo todas as portas se abriram, e todas as correntes [que prendiam] a todos se soltaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 16, 27, 'E o carcereiro, tendo acordado e visto abertas todas as portas da prisão; puxou a espada, [e] estava a ponto de se matar, pensando que os presos tinham fugido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 16, 28, 'Mas Paulo clamou em alta voz, dizendo: Não te faças nenhum mal, porque todos nós estamos aqui.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 16, 29, 'E tendo pedido luzes, saltou para dentro, e termendo muito, ele se prostrou diante de Paulo e Silas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 16, 30, 'E levando-os para fora, disse: Senhores, o que me é necessário fazer para eu me salvar?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 16, 31, 'E eles [lhe] disseram: Crê no Senhor Jesus Cristo, e serás salvo, tu e a tua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 16, 32, 'E lhe falaram da palavra do Senhor, e a todos os que estavam em sua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 16, 33, 'E ele, tomando-os consigo, naquela mesma hora da noite, lavou [-lhes] as feridas dos açoites, e logo foi batizado, ele e todos os seus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 16, 34, 'E tendo os levado a sua casa, pôs [comida] diante deles à mesa; e alegrou-se muito, tendo crido em Deus com toda a sua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 16, 35, 'E sendo [já] de dia, os magistrados mandaram aos guardas, dizendo: Solta aqueles homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 16, 36, 'E o carcereiro anunciou estas palavras a Paulo, [dizendo] : Os magistrados têm mandado vos soltar; portanto agora saí, e ide em paz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 16, 37, 'Mas Paulo lhes disse: Eles nos açoitaram publicamente, e sem sermos sentenciados, sendo nós homens romanos, lançaram-nos na prisão, e agora nos lançam fora às escondidas? [Assim] não! Mas que eles mesmos venham e nos tirem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 16, 38, 'E os guardas voltaram para dizer aos magistrados estas palavras; e eles temeram ao ouvirem que eram romanos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 16, 39, 'E tendo vindo, rogaram-lhes; e tirando-os, pediram [-lhes] que saíssem da cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 16, 40, 'E eles, tendo saído da prisão, entraram [na casa] de Lídia; e vendo aos irmãos, consolaram-lhes; e saíram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 17, 1, 'E viajando por Anfípolis e Apolônia, vieram a Tessalônica, onde havia uma sinagoga de judeus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 17, 2, 'E Paulo, como era de [seu] costume, entrou a eles, e por três sábados argumentava com eles pelas Escrituras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 17, 3, 'Declarando [-as] ,e propondo [-lhes] ,que era necessário que o Cristo morresse, e ressuscitasse dos mortos; e que ( [dizia ele] ) este Jesus é o Cristo, a quem eu vos anuncio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 17, 4, 'E alguns deles creram, e se ajuntaram a Paulo e Silas; e dos gregos devotos grande multidão; e não poucas das mulheres principais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 17, 5, 'Mas os judeus incrédulos, movidos de inveja, tomaram consigo alguns homens malignos dos mercados, e juntando uma multidão, tumultuaram a cidade; e atacando a casa de Jasão, procuravam trazê-los ao povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 17, 6, 'E não os achando, puxaram a Jasão, e a alguns irmãos às maiores autoridades da cidade, clamando: Estes que tem perturbado ao mundo também vieram até aqui.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 17, 7, 'Aos quais Jasão tem recolhido, e todos estes fazem contra as ordens de César, dizendo que há outro rei, [chamado] Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 17, 8, 'E eles tumultuaram a multidão, e às autoridades da cidade, que ouviam estas coisas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 17, 9, 'Mas tendo recebido fiança de Jasão e dos demais, eles os soltaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 17, 10, 'E logo os irmãos enviaram de noite a Paulo e a Silas até Bereia; os quais, ao chegarem lá, foram à sinagoga dos judeus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 17, 11, 'E estes foram mais nobres do que os que estavam em Tessalônica, [porque] os quais receberam a palavra com toda boa vontade, examinando a cada dia as escrituras, [para ver] se estas coisas eram assim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 17, 12, 'Portanto muitos deles realmente creram, e das mulheres gregas honradas; e dos homens, não poucos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 17, 13, 'Mas quando os judeus de Tessalônica souberam que também em Bereia a palavra de Deus era anunciada por Paulo, vieram também para lá, e incitaram as multidões.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 17, 14, 'Mas então no mesmo instante os irmãos despediram a Paulo, para que fosse ao mar; mas Silas e Timóteo continuaram ali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 17, 15, 'E os que conduziram a Paulo, levaram-no até Atenas; e tendo recebido ordem para Silas e Timóteo, para que viessem a ele o mais rápido [que pudessem] ,eles foram embora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 17, 16, 'E enquanto Paulo os esperava em Atenas, seu espírito se incomodava dentro dele, ao ver a cidade tão dedicada à idolatria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 17, 17, 'Então ele disputava muito na sinagoga, com os judeus, e com os religiosos; e no mercado a cada dia, com os que vinham [até ele] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 17, 18, 'E alguns dos filósofos epicureus e estoicos discutiam com ele; e uns diziam: O que quer dizer este tagarela?E outros: Parece que ele é pregador de deuses estranhos.Porque ele lhes anunciava o Evangelho de Jesus e a ressurreição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 17, 19, 'E tomando-o, trouxeram [-no] ao areópago, dizendo: Podemos nós saber que doutrina nova é esta que tu falas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 17, 20, 'Porque tu trazes coisas estranhas aos nossos ouvidos; então queremos saber o que isto quer dizer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 17, 21, '(E todos os atenienses e visitantes estrangeiros não se ocupavam de nenhuma outra coisa, a não ser em dizer e ouvir alguma novidade).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 17, 22, 'E Paulo, estando no meio do areópago, disse: Homens atenienses, eu vejo em tudo como vós sois muito religiosos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 17, 23, 'Porque enquanto eu passava [pela cidade] e via vossos santuários, achei também um altar, em que estava escrito: AO DEUS DESCONHECIDO. Este a quem vós prestais devoção sem conhecer, [este é o que] eu vos anuncio;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 17, 24, 'O Deus que fez o mundo, e todas as coisas que nele [há] ; este, sendo Senhor do céu e da terra, não habita em tempos feitos por mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 17, 25, 'E nem também é servido por mãos humanas; [como que] necessitasse de alguma coisa; [porque] ele [é que] dá a todos vida, respiração, e todas as coisas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 17, 26, 'E de um sangue ele fez toda nação humana, para habitarem sobre a face da terra, determinando os tempos desde antes ordenados, e o limites da morada [deles] ;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 17, 27, 'Para que buscassem ao Senhor, se talvez pudessem apalpá-lo e encontrá-lo,apesar dele não estar longe de cada um de nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 17, 28, 'Porque nele vivemos, e nos movemos, e somos; assim como também alguns de vossos poetas disseram; porque também nós somos descendência dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 17, 29, 'Sendo então descendência de Deus, nós não devemos pensar que a divindade seja semelhante a ouro, ou a prata, ou a pedra esculpida por artifício e imaginação humana.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 17, 30, 'Portanto Deus, tendo desconsiderado os tempos da [vossa] ignorância, agora anuncia a todos as pessoas, em todo lugar, para que se arrependam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 17, 31, 'Porque ele tem estabelecido um dia em que ele julgará ao mundo em justiça por meio do homem a quem determinou; dando certeza a todos, tendo o ressuscitado dos mortos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 17, 32, 'E ao ouvirem da ressurreição dos mortos, alguns zombavam; e outros diziam: Nós ouviremos sobre isto de ti na próxima vez.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 17, 33, 'E assim Paulo saiu do meio deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 17, 34, 'Porém, tendo chegado alguns homens até ele, creram; entre os quais estava também Dionísio o areopagita, e uma mulher de nome Dâmaris, e outros com eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 18, 1, 'E depois disto ele partiu de Atenas, e veio a Corinto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 18, 2, 'E achando a um certo judeu, de nome Áquila, natural de Ponto, que recentemente tinha vindo da Itália, e Priscila, sua mulher (porque Cláudio tinha mandado que todos os judeus saíssem de Roma), veio até eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 18, 3, 'E porque era do mesmo ofício, ficou com eles, e trabalhava; porque tinham o ofício de fazerem tendas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 18, 4, 'E ele disputava na sinagoga a cada sábado; e persuadia a judeus e a gregos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 18, 5, 'E quando Silas e Timóteo desceram da Macedônia, Paulo foi pressionado pelo Espírito, dando testemunho aos judeus [de que] o Cristo [era] Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 18, 6, 'Mas tendo eles resistido e blasfemado, ele sacudiu as roupas, e lhes disse: Vosso sangue [seja] sobre vossa cabeça; eu estou limpo; e a partir de agora irei aos gentios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 18, 7, 'E tendo saído dali, entrou na cada de um, de nome Justo, que servia a Deus, cuja casa era vizinha à sinagoga.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 18, 8, 'E Crispo, o chefe da sinagoga, creu no Senhor com toda a sua casa; e muitos dos coríntios, tendo ouvido, creram e foram batizados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 18, 9, 'E o Senhor disse em visão de noite a Paulo: Não temas, mas fala, e não te cales.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 18, 10, 'Porque eu estou contigo, e ninguém porá [mão] em ti para te fazer mal, porque eu tenho muito povo nesta cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 18, 11, 'E ele ficou [ali por] um ano e seis meses, ensinando entre eles a palavra de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 18, 12, 'Mas sendo Gálio o procônsul da Acaia, os judeus se levantaram em concordância contra Paulo, e o trouxeram ao tribunal,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 18, 13, 'Dizendo: Este persuade as pessoas a servirem a Deus contra a Lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 18, 14, 'E Paulo, querendo abrir a boca, Gálio disse aos judeus: Se houvesse algum mau ato ou crime grande, ó judeus, com razão eu vos suportaria;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 18, 15, 'Mas se a questão é de palavra [s] , e de nomes, e da Lei que há entre vós, vede [-o] vós mesmos; porque destas coisas eu não quero ser juiz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 18, 16, 'E ele os tirou do tribunal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 18, 17, 'Mas todos os gregos, tomando a Sóstenes, o chefe da sinagoga, feriram [-no] diante do tribunal; e a nada destas coisas Gálio dava importância.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 18, 18, 'E Paulo, ficando ali ainda muitos dias, ele se despediu dos irmãos, e dali navegou para a Síria, e juntos com ele [estavam] Priscila e Áquila; tendo rapado a cabeça em Cencreia, porque ele tinha [feito] voto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 18, 19, 'E chegou a Éfeso, e os deixou ali; mas ele, entrando na sinagoga, disputava com os judeus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 18, 20, 'E eles, pedindo[-lhe] que continuasse com eles por mais [algum] tempo, ele não concordou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 18, 21, 'Porém despediu-se deles, dizendo: De toda maneira tenho que estar na festa que vem em Jerusalém; mas outra vez, se Deus quiser, voltarei a vós.E ele saiu de Éfeso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 18, 22, 'E tendo vindo a Cesareia, subiu e, saudando à igreja, desceu a Antioquia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 18, 23, 'E passando [ali] algum tempo, ele partiu, passando em sequência pela região da Galácia e Frígia, firmando a todos os discípulos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 18, 24, 'E chegou a Éfeso um certo judeu, de nome Apolo, natural de Alexandria, homem eloquente, bem capacitado nas Escrituras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 18, 25, 'Este era instruído no caminho do Senhor; e fervoroso de espírito, falava e ensinava corretamente as coisas do Senhor; [ainda que] soubesse somente o batismo de João.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 18, 26, 'E este começou a falar ousadamente na sinagoga; e Áquila e Priscila, ao o ouvirem, tomaram-no consigo, e explicaram mais detalhadamente o caminho de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 18, 27, 'E ele, querendo passar a Acaia, os irmãos o exortaram, [e] escreveram aos discípulos que o recebessem; o qual, tendo chegado, auxiliou muito aos que tinham crido pela graça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 18, 28, 'Porque vigorosamente ele provava publicamente os erros dos judeus, mostrando pelas Escrituras que Jesus era o Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 19, 1, 'E enquanto Apolo estava em Corinto, aconteceu que, tendo Paulo passado por todas as regiões altas, ele veio a Éfeso; e achando [ali] alguns discípulos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 19, 2, 'Disse-lhes: Vós [já] recebestes o Espírito Santo [desde que] crestes? E eles lhe disseram: Nós nem tínhamos ouvido falar que havia Espírito Santo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 19, 3, 'E ele lhes disse: Em que vós fostes batizados? E eles disseram: No batismo de João.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 19, 4, 'Então Paulo disse: João verdadeiramente batizou [com] o batismo do arrependimento, dizendo ao povo que cressem naquele que viria após ele, isto é, em Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 19, 5, 'Ao ouvirem [isto] , eles foram batizados no nome do Senhor Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 19, 6, 'E Paulo, impondo-lhes as mãos, veio sobre eles o Espírito Santo; e falavam em línguas, e profetizavam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 19, 7, 'E todos os homens eram cerca de doze.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 19, 8, 'E ele, entrando na sinagoga, falava ousadamente durante três meses, disputando e persuadindo as coisas do Reino de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 19, 9, 'Mas quando alguns se endureceram, e não creram, e falando mal do Caminho diante da multidão, ele se desviou deles; e separou aos discípulos, disputando a cada dia na escola de um certo Tirano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 19, 10, 'E isto aconteceu durante dois anos; de tal maneira que todos os que habitavam na Ásia tinham ouvido a palavra do Senhor Jesus, tanto judeus como gregos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 19, 11, 'E Deus fazia milagres extraordinários pelas mãos de Paulo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 19, 12, 'De tal maneira que até os lenços e aventais de seu corpo eram levados aos enfermos, e as doenças os deixavam, e os espíritos malignos saíam deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 19, 13, 'E alguns exorcistas dos judeus, itinerantes, tentaram invocar o nome do Senhor Jesus sobre os que tinham espíritos malignos, dizendo: Nós vos repreendemos por Jesus, a quem Paulo prega.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 19, 14, 'E eram sete filhos de Ceva, judeu, chefe dos sacerdotes, os que faziam isto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 19, 15, 'Mas o espírito maligno respondeu: Eu conheço Jesus, e sei quem é Paulo; mas vós, quem sois?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 19, 16, 'E o homem em quem estava o espírito maligno saltou sobre eles, e dominando-os, foi mais forte do que eles; de tal maneira que eles fugiram nus e feridos daquela casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 19, 17, 'E isto se fez conhecido a todos que habitavam em Éfeso, tanto a judeus como a gregos; e caiu temor sobre todos eles; e [assim] foi engrandecido o nome do Senhor Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 19, 18, 'E muitos dos que criam vinham, confessando e declararando as suas atitudes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 19, 19, 'Também muitos dos que praticavam ocultismo trouxeram seus livros, e [os] queimaram na presença de todos; e calcularam o preço deles, e acharam que [custavam] cinquenta mil [moedas] de prata.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 19, 20, 'Assim a palavra do Senhor crescia e prevalecia poderosamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 19, 21, 'E quando se cumpriram estas coisas, Paulo propôs em espírito que, passando pela Macedônia e Acaia, ir até Jerusalém, dizendo: Depois de eu estar lá, também tenho que ver Roma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 19, 22, 'E ele, tendo enviado à Macedônia dois daqueles que o serviam, Timóteo e Erasto, ele ficou por [algum] tempo na Ásia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 19, 23, 'Mas naquele tempo aconteceu um não pequeno alvoroço quanto ao Caminho .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 19, 24, 'Porque um certo artífice de prata, de nome Demétrio, que fazia objetos de prata para o templo de Diana , e dava não pouco lucro aos artesãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 19, 25, 'Aos quais, tendo os reunido com os trabalhadores de semelhantes coisas, disse: Homens, vós sabeis que deste ofício temos nossa prosperidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 19, 26, 'E vós estais vendo e ouvindo que este Paulo, não somente em Éfeso, mas até quase em toda a Ásia, tem persuadido e apartado uma grande multidão, dizendo que não são deuses os que são feitos com as mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 19, 27, 'E não somente há perigo de que isto torne [nosso] ofício em desprezo, mas também que [até] o tempo da grande deusa Diana seja considerado inútil, e que a grandiosidade dela, a quem toda a Ásia e o mundo venera, venha a ser destruída.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 19, 28, 'E eles, ao ouvirem [estas coisas] ,encheram-se de ira, e clamaram, dizendo: Grande é a Diana dos efésios!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 19, 29, 'E toda a cidade se encheu de tumulto, e em concordância eles invadiram ao teatro, tomando consigo Gaio e Aristarco, macedônios, companheiros de Paulo na viagem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 19, 30, 'E Paulo, querendo comparecer diante do povo, os discípulos não o permitiram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 19, 31, 'E também alguns dos líderes da Ásia, que eram amigos dele, enviaram-lhe [aviso] , rogando[-lhe] para que não se apresentasse no teatro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 19, 32, 'Então gritavam, [alguns de uma maneira] , outros de outra; porque a aglomeração estava confusa; e a maioria não sabia por que causa estavam aglomerados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 19, 33, 'E tiraram da multidão a Alexandre, os judeus o pondo para a frente. E Alexandre, acenando com a mão, queria [se] defender ao povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 19, 34, 'Mas ao saberem que ele era judeu, levantou-se uma voz de todos, clamando por cerca de duas horas: Grande é a Diana dos efésios!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 19, 35, 'E o escrivão, tendo apaziguado a multidão, disse: Homens efésios, quem não sabe que a cidade dos efésios é a guardadora do templo da grande deusa Diana, e da [imagem] que desceu do céu?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 19, 36, 'Portanto, sendo que estas coisas não podem ser contraditas, vós deveis vos acalmar, e nada façais precipitadamente;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 19, 37, 'Porque vós trouxestes [aqui] estes homens, que nem são sacrílegos, nem blasfemam de vossa deusa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 19, 38, 'Então se Demétrio e os artesãos que estão com ele tem algum assunto contra ele, os tribunais estão abertos, e há procônsules; que se acusem uns aos outros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 19, 39, 'E se procurais alguma outra coisa, será decidido em uma reunião legalizada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 19, 40, 'Porque corremos perigo de que hoje sejamos acusados de rebelião, tendo causa nenhuma para dar como explicação para este tumulto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 19, 41, 'E tendo dito isto, despediu o ajuntamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 20, 1, 'E tendo acabado o tumulto, Paulo chamou a si os discípulos e, abraçando-os, saiu para ir à Macedônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 20, 2, 'E tendo passado por aquelas regiões, e exortando-os com muitas palavras, ele veio à Grécia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 20, 3, 'E ficando [ali] por três meses, e havendo contra ele uma cilada posta pelos judeus quando ele estava a ponto de navegar para a Síria, ele decidiu voltar pela Macedônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 20, 4, 'E o acompanhou até a Ásia Sópater, de Bereia; e dos tessalonicenses, Aristarco e Segundo, e Gaio de Derbe, e Timóteo; e dos da Ásia, Tíquico e Trófimo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 20, 5, 'Estes, indo adiante, nos esperaram em Trôade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 20, 6, 'E depois dos dias dos [pães] não fermentados, nós navegamos de Filipos, e em cinco dias viemos até eles, onde ficamos por sete dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 20, 7, 'E no primeiro [dia] da semana, tendo os discípulos se reunido para partir o pão, Paulo discutia com eles, estando para partir no dia seguinte; e ele estendeu a discussão até a meia noite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 20, 8, 'E havia muitas luminárias no compartimento onde estavam reunidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 20, 9, 'E estando um certo rapaz, de nome Êutico, sentado em uma janela, tendo sido tomado por um sono profundo, [e] ,estando Paulo [ainda] falando por muito [tempo] ,[Êutico] ,derrubado pelo sono, caiu desde o terceiro andar abaixo; e foi levantado morto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 20, 10, 'Mas Paulo, tendo descido, debruçou sobre ele e, abraçando [-o] ,disse: Não fiqueis perturbados, porque sua alma [ainda] está nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 20, 11, 'E [voltou] a subir, e tendo partido e experimentado o pão, ele falou longamente até o nascer do dia; e assim ele partiu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 20, 12, 'E trouxeram o rapaz vivo, e ficaram não pouco consolados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 20, 13, 'E nós, tendo ido adiante ao navio, navegamos até Assôs, onde estaríamos para receber a Paulo, porque assim ele tinha ordenado; e ele ia a pé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 20, 14, 'E quando ele se encontrou conosco em Assôs, nós o tomamos, e fomos a Mitilene.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 20, 15, 'E navegando dali, chegamos no [dia] seguinte em frente a Quios; e no outro dia aportamos em Samos; e ficando em Trogílio, no dia seguinte viemos a Mileto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 20, 16, 'Porque Paulo tinha decidido navegar [desviando-se] de Éfeso, para não lhe haver de gastar tempo na Ásia; porque ele se apressava para estar em Jerusalém do dia de Pentecostes, caso lhe fosse possível.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 20, 17, 'Mas ele enviou [mensagem] desde Mileto até Éfeso, chamando aos anciãos da igreja.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 20, 18, 'E quando vieram a [Paulo] ,ele lhes disse: Vós sabeis que desde o primeiro dia que entrei na Ásia, [o modo] como eu estive todo [aquele] tempo convosco;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 20, 19, 'Servindo ao Senhor com toda humildade, muitas lágrimas, e tentações, que sobrevieram a mim pelas ciladas dos judeus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 20, 20, 'Como eu, daquilo que [vos] era proveitoso, nada deixei de anunciar a vós, e ensinar publicamente e pelas casas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 20, 21, 'Dando testemunho, tanto a judeus como a gregos, do arrependimento para [se converter] a Deus, e da fé em nosso Senhor Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 20, 22, 'E agora eis que, estando eu atado ao Espírito, estou indo a Jerusalém, não sabendo o que me acontecerá;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 20, 23, 'A não ser pelo que o Espírito Santo em cada cidade [me] dá testemunho, dizendo que prisões e aflições me esperam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 20, 24, 'Mas de nenhuma [dessas] coisas eu dou importância, nem tenho minha vida por preciosa, para que com alegria eu cumpra minha carreira, e o trabalho que recebi do Senhor Jesus, para dar testemunho do Evangelho da graça de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 20, 25, 'E agora, eis que eu sei que todos vós, a quem eu passei pregando o Reino de Deus, não vereis mais o meu rosto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 20, 26, 'Portanto eu vos dou claro testemunho de que eu estou limpo do sangue de todos [vós] ;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 20, 27, 'Porque eu não deixei de vos anunciar todo o conselho de Deus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 20, 28, 'Portanto prestai atenção por vós mesmos, e por todo o rebanho sobre os quais o Espírito Santo tem vos posto como supervisores, para apascentardes a igreja de Deus, a qual ele adquiriu por meio de seu próprio sangue.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 20, 29, 'Porque isto eu sei, que depois de minha partida, entrarão entre vós lobos cruéis, que não pouparão ao rebanho;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 20, 30, 'E que dentre vós mesmos se levantarão homens a falarem coisas perversas, para atraírem após si aos discípulos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 20, 31, 'Por isso vigiai, lembrando que por três anos, noite e dia eu não parei de vos alertar com lágrimas a cada um [de vós] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 20, 32, 'E agora, irmãos, eu vos entrego a Deus, e à palavra de sua graça; ele que é poderoso para vos edificar e vos dar herança entre todos os santificados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 20, 33, 'Eu não cobicei de ninguém a prata, nem ouro, nem roupa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 20, 34, 'E vós mesmos sabeis que, para as minhas necessidades e as dos que estavam comigo, estas [minhas] mãos me serviram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 20, 35, 'Em tudo eu vos tenho mostrado que trabalhando assim, é necessário dar suporte aos enfermos; e lembrar-se das palavras do Senhor Jesus, que disse: Mais bem-aventurado é dar do que receber.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 20, 36, 'E tendo dito isto, pondo-se de joelhos, ele orou com todos eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 20, 37, 'E houve um grande pranto de todos; e reclinando-se sobre o pescoço de Paulo, beijavam-no;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 20, 38, 'Entristecendo-se muito, principalmente pela palavra que ele tinha dito, que não mais veriam o rosto dele; e o acompanharam até o navio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 21, 1, 'E quando aconteceu de termos saído deles, e navegado, percorremos diretamente, e viemos a Cós, e [n] o [dia] seguinte a Rodes, e dali a Pátara.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 21, 2, 'E tendo achado um navio que passava para a Fenícia, nós embarcamos nele, e partimos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 21, 3, 'E tendo Chipre à vista, e deixando-a à esquerda, navegamos para a Síria, e viemos a Tiro; porque o navio tinha de deixar ali sua carga.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 21, 4, 'E nós ficamos ali por sete dias; e achamos aos discípulos, os quais diziam pelo Espírito a Paulo, que não subisse a Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 21, 5, 'E tendo passado [ali] aqueles dias, nós saímos e seguimos nosso caminho, acompanhando-nos todos com [suas] mulheres e filhos até fora da cidade; e postos de joelhos na praia, oramos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 21, 6, 'E saudando-nos uns aos outros, subimos ao navio; e eles voltaram para as [casas] deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 21, 7, 'E nós, acabada a navegação de Tiro, chegamos a Ptolemaida; e tendo saudado aos irmãos, ficamos com eles por um dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 21, 8, 'E [n] o [dia] seguinte, Paulo e nós que estávamos com ele, saindo dali, viemos a Cesareia; e entrando na casa de Filipe, o evangelista (que era [um] dos sete), nós ficamos com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 21, 9, 'E este tinha quatro filhas, que profetizavam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 21, 10, 'E ficando nós [ali] por muitos dias, desceu da Judeia um profeta, de nome Ágabo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 21, 11, 'E ele, tendo vindo a nós, e tomando a cinta de Paulo, e atando-se os pés e as mãos, disse: Isto diz o Espírito Santo: Assim os judeus em Jerusalém atarão ao homem a quem [pertence] esta cinta, e o entregarão nas mãos dos gentios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 21, 12, 'E nós, tendo ouvido isto, rogamos a ele, tanto nós como os que eram daquele lugar, que ele não subisse a Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 21, 13, 'Mas Paulo respondeu: O que vós estais fazendo, ao chorarem e afligirem o meu coração? Porque eu estou pronto, não somente para ser atado, mas até mesmo para morrer em Jerusalém, pelo nome do Senhor Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 21, 14, 'E como ele não deixou ser persuadido, nós nos aquietamos, dizendo: Faça-se a vontade do Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 21, 15, 'E depois daqueles dias, nós nos arrumamos, e subimos a Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 21, 16, 'E foram também conosco [alguns] dos discípulos de Cesareia, trazendo [consigo] a um certo Mnáson, cipriota, discípulo antigo, com o qual íamos nos hospedar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 21, 17, 'E quando chegamos a Jerusalém, os irmãos nos receberam com muito boa vontade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 21, 18, 'E [n] o [dia] seguinte, Paulo entrou conosco a [casa de] Tiago, e todos os anciãos vieram ali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 21, 19, 'E tendo os saudado, ele [lhes] contou em detalhes o que Deus tinha feito entre os gentios por meio do trabalho dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 21, 20, 'E eles, ao ouvirem, glorificaram ao Senhor, e lhe disseram: Tu vês, irmão, quantos milhares de judeus há que creem, e todos são zelosos da lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 21, 21, 'E foram informados quanto a ti, que a todos os judeus, que estão entre os gentios, [que] tu ensinas a se afastarem de Moisés, dizendo que não devem circuncidar [seus] filhos, nem andar segundo os costumes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 21, 22, 'Então o que se fará? Em todo caso a multidão deve se ajuntar, porque ouvirão que tu [já] chegaste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 21, 23, 'Portanto faça isto que te dizemos: temos quatro homens que fizeram voto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 21, 24, 'Toma contigo a estes, e purifica-te com eles, e paga os gastos deles, para que rapem a cabeça, e todos saibam que não há nada do que foram informados sobre ti, mas sim, [que] tu mesmo andas guardando a Lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 21, 25, 'E quanto aos que creem dentre os gentios, nós já escrevemos, julgando que nada disto guardassem, a não ser somente que se abstenham do que se abstenham das coisas sacrificadas aos ídolos, e do sangue, e da [carne] sufocada, e do pecado sexual.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 21, 26, 'Então Paulo, tendo tomado consigo a aqueles homens, e purificando-se com eles no dia seguinte, entrou no Templo, anunciando que [já] estavam cumpridos dos dias da purificação, quando fosse oferecida por eles, cada um [sua] oferta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 21, 27, 'E tendo os sete dias quase quase completados, os judeus da Ásia, vendo-o, tumultuaram a todo o povo, e lançaram as mãos sobre ele [para o deterem] ,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 21, 28, 'Clamando: Homens israelitas, ajudai [-nos] ; este é o homem que por todos os lugares ensina a todos contra o [nosso] povo, e contra a Lei, e [contra] este lugar; e além disto, ele também pôs gregos dentro do Templo, e contaminou este santo lugar!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 21, 29, '(Porque antes eles tinham visto na cidade a Trófimo junto dele, ao qual pensavam que Paulo tinha trazido para dentro do Templo).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 21, 30, 'E toda a cidade se tumultuou, e houve um ajuntamento do povo; e tendo detido a Paulo, trouxeram-no para fora do Templo; e logo as portas foram fechadas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 21, 31, 'E eles, procurando matá-lo, a notícia chegou ao comandante e aos soldados, de que toda Jerusalém estava em confusão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 21, 32, 'O qual, tendo tomado logo consigo soldados e centuriões, correu até eles. E eles, vendo ao comandante e aos soldados, pararam de ferir a Paulo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 21, 33, 'Então o comandante, tendo se aproximado, prendeu-o, e mandou que ele fosse atado em duas correntes; e perguntou quem ele era, e o que ele tinha feito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 21, 34, 'E na multidão clamavam [uns de uma maneira] ,e outros de outra maneira; mas [como] ele não podia saber com certeza por causa do tumulto, ele mandou que o levassem para a área fortificada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 21, 35, 'E ele, tendo chegado às escadas, aconteceu que ele foi carregado pelos soldados, por causa da violência da multidão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 21, 36, 'Porque a multidão do povo [o] seguia, gritando: Tragam-no para fora!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 21, 37, 'E Paulo, estando perto de entrar na área fortificada, disse ao comandante: É permitido a mim te falar alguma coisa?E ele disse: Tu sabes grego?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 21, 38, 'Por acaso não és tu aquele egípcio, que antes destes dias tinha levantando uma rebelião, e levou ao deserto quatro mil homens assassinos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 21, 39, 'Mas Paulo lhe disse: Na verdade eu sou um homem judeu de Tarso, cidade não pouca importância da Cilícia; mas eu te rogo para que tu me permitas falar ao povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 21, 40, 'E tendo [lhe] permitido, Paulo pôs-se de pé nas escadas, acenou com a mão ao povo; e tendo havido grande silêncio, falou [-lhes] em língua hebraica, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 22, 1, 'Homens irmãos, e pais, ouvi agora minha defesa para convosco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 22, 2, 'E tendo ouvido que ele lhes falava em língua hebraica, fizeram ainda mais silêncio. E ele disse:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 22, 3, 'Eu verdadeiramente sou um homem judeu, nascido em Tarso da Cilícia, e criado nesta cidade aos pés de Gamaliel, ensinado ao mais correto modo da Lei paterna [e] zeloso de Deus, assim como todos vós sois hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 22, 4, '[Eu] ,que persegui este caminho até a morte, atando tanto a homens como a mulheres, e [os] entregando a prisões.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 22, 5, 'Assim como também o sumo sacerdote me é testemunha, e todo o conselho dos anciãos; dos quais eu, tendo tomado cartas para os irmãos, fui a Damasco para que os que estivessem ali, eu também os trouxesse amarrados a Jerusalém, para que fossem castigados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 22, 6, 'Mas aconteceu que, estando eu no caminho, e chegando perto de Damasco, quase ao meio dia, de repente uma grande luz do céu brilhou ao redor de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 22, 7, 'Eu cai ao chão, e ouvi uma voz, que me dizia: Saulo, Saulo, por que me persegues?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 22, 8, 'E eu respondi: Quem és, Senhor? E ele me disse: Eu sou Jesus, o nazareno, a quem tu persegues.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 22, 9, 'E os que estavam comigo verdadeiramente viram a luz, e ficaram muito atemorizados; mas eles não ouviram a voz daquele que falava comigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 22, 10, 'E eu disse: Que farei, Senhor? E o Senhor me disse: Levanta-te, e vai a Damasco, e ali te será dito tudo o que te é ordenado fazer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 22, 11, 'E quando eu não [conseguia] ver, por causa da glória daquela luz, eu fui levado pela mão dos que estavam comigo, e [assim] cheguei a Damasco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 22, 12, 'E um certo Ananias, homem devoto conforme a Lei, que tinha [bom] testemunho de todos os judeus que moravam [ali] ;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 22, 13, 'Tendo vindo até mim, e ficando [diante de mim] ,ele me disse: Irmão Saulo, recupere a vista; E naquela mesma hora eu [pude] vê-lo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 22, 14, 'E ele disse: O Deus de nossos pais te predeterminou para que tu conheças a vontade dele, e vejas aquele justo, e tu ouças a voz de sua boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 22, 15, 'Porque tu serás testemunha dele para com todos as pessoas, daquilo que tens visto e ouvido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 22, 16, 'E agora, por que estás parado? Levanta-te, e sê batizado, e lava teus pecados, invocando o nome do Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 22, 17, 'E aconteceu a mim, tendo eu voltado a Jerusalém, e estando orando no Templo, veio-me um êxtase;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 22, 18, 'E eu vi aquele que me dizia: Apressa-te, e sai logo de Jerusalém, porque não aceitarão teu testemunho sobre mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 22, 19, 'E eu disse: Senhor, eles sabem que eu prendia e açoitava nas sinagogas aqueles que criam em ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 22, 20, 'E quando o sangue de Estêvão, tua testemunha, se derramava, eu também estava presente, e consentia em sua morte, e guardava as roupas daqueles que o matavam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 22, 21, 'E ele me disse: Vai, porque eu te enviarei para longe, aos gentios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 22, 22, 'E eles o ouviram até esta palavra, e [em seguida] levantaram suas vozes, dizendo: Extermina-o da terra! Porque não é bom que ele viva.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 22, 23, 'E enquanto eles gritavam, tiravam [suas] capas, e lançavm pó ao ar,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 22, 24, 'O comandante mandou que o levassem à área fortificada, dizendo que o interrogassem com açoites, para saber por que causa clamavam assim contra ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 22, 25, 'E quando estavam o atando com correias, Paulo disse ao centurião que estava ali: É lícito para vós açoitar a um homem romano, sem [ter sido] condenado?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 22, 26, 'E o centurião, tendo ouvido [isto] ,foi e avisou ao comandante, dizendo: Olha o que estás a ponto de fazer, porque este homem é romano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 22, 27, 'E o comandante, tendo se aproximado, disse-lhe: Dize-me, tu és romano?E ele disse: Sim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 22, 28, 'E o comandante respondeu: Eu com muita soma [de dinheiro] obtive esta cidadania [romana] .E Paulo disse: E eu [a tenho] desde que nasci.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 22, 29, 'Então logo se afastaram dele aqueles que estavam para interrogá-lo; e até o comandante teve temor, ao entender que [Paulo] era romano, e que tinha o atado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 22, 30, 'E no[dia] seguinte, querendo saber corretamente a causa de por que ele era acusado pelos judeus, ele o soltou das correntes, e mandou vir aos chefes dos sacerdotes e todo o supremo conselho deles; e tendo trazido a Paulo, apresentou [-o] diante deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 23, 1, 'E Paulo, olhando fixamente para o supremo conselho, disse: Homens irmãos, com toda boa consciência eu tenho andado diante de Deus até o dia de hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 23, 2, 'Mas o sumo sacerdote Ananias mandou aos que estavam perto dele, que o espancassem na boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 23, 3, 'Então Paulo lhe disse: Deus vai te espancar, parede caiada! Estás tu [aqui] sentado para me julgar conforme a Lei, e contra a Lei mandas me espancarem?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 23, 4, 'E os que estavam ali disseram: Tu insultas ao sumo sacerdote de Deus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 23, 5, 'E Paulo disse: Eu não sabia, irmãos, que ele era o sumo sacerdote; porque está escrito: Não falarás mal do chefe do teu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 23, 6, 'E Paulo, sabendo que uma parte era de saduceus, e outra de fariseus, ele clamou no supremo conselho: Homens irmãos, eu sou fariseu, filho de fariseu; pela esperança e ressurreição dos mortos eu estou sendo julgado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 23, 7, 'E ele, tendo dito isto, houve uma confusão entre os fariseus e saduceus; e a multidão se dividiu;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 23, 8, 'Porque os saduceus dizem que não há ressurreição, nem anjo ou espírito; mas os fariseus declaram ambas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 23, 9, 'E houve uma grande gritaria; e levantando-se os escribas da parte dos fariseus, disputavam, dizendo: Nenhum mal achamos neste homem; e se algum espírito ou anjo falou com ele, não briguemos contra Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 23, 10, 'E havendo grande confusão, o comandante, temendo que Paulo não fosse despedaçado por eles, mandou descer a tropa, e tirá-lo do meio deles, e levá-lo à área fortificada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 23, 11, 'E [n] a noite seguinte o Senhor, aparecendo-lhe, disse: Tem bom ânimo, Paulo! Porque assim como deste testemunho de mim em Jerusalém, assim é necessário que tu dês testemunho também em Roma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 23, 12, 'E tendo vindo o dia, alguns dos judeus fizeram uma conspiração, e prestaram juramento sob pena de maldição, dizendo que não comeriam nem beberiam enquanto não matassem a Paulo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 23, 13, 'E eram mais de quarenta os que fizeram este juramento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 23, 14, 'Os quais foram até os chefes dos sacerdotes e os anciãos, [e] disseram: Fizemos juramento sob pena de maldição, de que nada experimentaremos enquanto não matarmos a Paulo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 23, 15, 'Agora, pois, vós, com o supremo conselho, informai ao comandante que amanhã ele o traga perante vós, como se fosse para que investigueis mais detalhadamente; e antes que ele chegue, estaremos prontos para o matar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 23, 16, 'E o filho da irmã de Paulo, tendo ouvido esta cilada, veio e entrou na área fortificada, e avisou a Paulo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 23, 17, 'E Paulo, tendo chamado a si um dos centuriões, disse: Leva este rapaz ao comandante, porque ele tem algo para lhe avisar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 23, 18, 'Então ele o tomou, levou ao comandante, e disse: O prisioneiro Paulo, tendo me chamado, rogou [-me] que eu te trouxesse este rapaz, que tem algo a te dizer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 23, 19, 'E o comandante, tomando-o pela mão, e indo para um lugar reservado, perguntou [-lhe] : O que tens para me avisar?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 23, 20, 'E ele disse: Os judeus combinaram de te pedirem que amanhã tu leves a Paulo ao supremo conselho, como se fosse para que lhe perguntem mais detalhadamente;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 23, 21, 'Porém tu, não acredites neles; porque mais de quarenta homens deles estão lhe preparando cilada, os quais sob pena de maldição fizeram juramento para não comerem nem beberem enquanto não o tiverem matado; e eles já estão preparados, esperando de ti a promessa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 23, 22, 'Então o comandante despediu ao rapaz, mandando [-lhe] : A ninguém digas que tu me revelaste estas coisas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 23, 23, 'E ele, chamando a si certos dois dos centuriões, disse: Aprontai duzentos soldados para irem até Cesareia; e setenta cavaleiros, e duzentos arqueiros, a partir das terceira hora da noite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 23, 24, 'E preparem animais para cavalgarem, para que pondo neles a Paulo, levem [-no] a salvo ao governador Félix.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 23, 25, 'E ele [lhe] escreveu uma carta, que continha este aspecto:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 23, 26, 'Cláudio Lísias, a Félix, excelentíssimo governador, saudações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 23, 27, 'Este homem foi preso pelos judeus, e estando já a ponte de o matarem, eu vim com a tropa e [o] tomei, ao ser informado que ele era romano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 23, 28, 'E eu, querendo saber a causa por que o acusavam, levei-o ao supremo conselho deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 23, 29, 'O qual eu achei que acusavam de algumas questões da Lei deles; mas que nenhum crime digno de morte ou de prisão havia contra ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 23, 30, 'E tendo sido avisado de que os judeus estavam para pôr uma cilada contra este homem, logo eu [o] enviei a ti, mandando também aos acusadores que diante de ti digam o que [tiverem] contra ele. Que tu estejas bem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 23, 31, 'Tendo então os soldados tomado a Paulo, assim como lhes tinha sido ordenado, trouxeram-no durante a noite a Antipátride.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 23, 32, 'E no [dia] seguinte, deixando irem com ele os cavaleiros, voltaram à área fortificada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 23, 33, 'Os quais, tendo chegado a Cesareia, e entregado a carta ao governador, apresentaram-lhe também a Paulo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 23, 34, 'E o governador, tendo lido [a carta] , perguntou de que província ele era; e ao entender que [era] da Cilícia,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 23, 35, 'disse: “Eu te ouvirei quando também chegarem os teus acusadores”. E mandou que o guardassem no palácio de Herodes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 24, 1, 'E cinco dias depois, desceu o sumo sacerdote Ananias, com os anciãos e um certo orador Tértulo; os quais compareceram diante do governador contra Paulo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 24, 2, 'E sendo chamado, Tértulo começou a acusá [-lo] , dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 24, 3, '[Visto que] há muita paz por causa de ti, e que por teu governo muitos bons serviços estão sendo feitos a esta nação, excelentíssimo Félix, totalmente e em todo lugar, com todo agradecimento o reconhecemos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 24, 4, 'Mas para que eu não gaste muito o teu tempo, rogo [-te] que tu nos ouças brevemente, conforme a tua clemência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 24, 5, 'Porque nós temos achado que este homem [é] uma peste, e levantador de rebeliões entre todos os judeus pelo mundo, e o principal defensor da seita dos nazarenos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 24, 6, 'O qual também tentou profanar o Templo; ao qual também prendemos, e quisemos julgar conforme a nossa Lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 24, 7, 'Mas tendo vindo sobre [nós] o comandante Lísias, com grande violência, tirou [-o] das nossas mãos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 24, 8, 'investigando-o tu mesmo, poderás entender todas estas coisas das quais o acusamos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 24, 9, 'E os judeus também concordaram, dizendo serem estas coisas assim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 24, 10, 'Mas Paulo, fazendo gesto ao governador para que falasse, respondeu: Sabendo eu que por muitos anos tu tens sido juiz desta nação, com maior ânimo eu me defendo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 24, 11, 'Pois tu podes entender que há não mais que doze dias, eu tinha subido a Jerusalém para adorar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 24, 12, 'E nem me acharam falando com alguém no Templo, nem incitando ao povo, nem nas sinagogas, nem na cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 24, 13, 'E nem podem provar as coisas das quais agora estão me acusando.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 24, 14, 'Mas isto eu te confesso, que conforme o Caminho que eles chamam de seita, assim eu sirvo ao Deus dos [meus] pais, crendo em tudo que está escrito na Lei e nos profetas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 24, 15, 'Tendo esperança em Deus, ao qual estes mesmos também esperam, que vai haver ressurreição dos mortos, tanto dos justos como dos injustos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 24, 16, 'E nisto eu pratico, [em que] tanto para com Deus como para com os seres humanos eu sempre tenha uma consciência limpa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 24, 17, 'E muitos anos depois, vim para fazer doações e ofertas à minha nação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 24, 18, 'Nisto, tendo eu me purificado, nem com multidões, nem com tumulto, alguns judeus da Ásia me acharam,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 24, 19, 'Os quais era necessário que estivessem [aqui] presentes diante de ti, se tivessem alguma coisa contra mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 24, 20, 'Ou digam estes mesmos, se eles acharam alguma má ação em mim quando eu estava perante o supremo conselho;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 24, 21, 'A não ser somente esta palavra com que, quando eu estava entre eles, clamei, que pela ressurreição dos mortos eu estou sendo julgado hoje por vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 24, 22, 'Tendo ouvido estas coisas, Félix, que sabia mais detalhadamente sobre o Caminho, adiou-lhes, dizendo: Quando o comandante Lísias descer, eu procurarei saber melhor de vossos assuntos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 24, 23, 'E ele mandou ao centurião que guardassem a Paulo, e estivesse com [alguma] liberdade, e impedir a ninguém dos seus [amigos] lhe prestasse serviço, ou vir até ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 24, 24, 'E alguns dias depois, tendo vindo Félix com a mulher dele Drusila, que era judia, mandou chamar a Paulo, e o ouviu sobre a fé em Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 24, 25, 'E ele, tendo discursado sobre a justiça, o domínio próprio, e o julgamento que está por vir, Félix temeu, [e] respondeu: Por agora vai; e tendo [outra] oportunidade, eu te chamarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 24, 26, 'Ele também esperava que lhe fosse dado [algum] dinheiro por Paulo, para que o soltasse; por isso ele também muitas vezes o mandava chamar, e conversava com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 24, 27, 'Mas tendo completado dois anos, Félix teve por sucessor a Pórcio Festo. E Félix, querendo agradar dos judeus, deixou Paulo preso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 25, 1, 'Então Festo, tendo entrado na província, subiu dali três dias depois de Cesareia a Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 25, 2, 'E o sumo sacerdote e os líderes dos judeus compareceram diante dele contra Paulo, e lhe rogaram;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 25, 3, 'Pedindo favor contra ele, para que o fizesse vir a Jerusalém, preparando cilada para o matarem no caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 25, 4, 'Mas Festo respondeu que Paulo estava guardado em Cesareia, e que ele logo estava indo [para lá] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 25, 5, 'Ele disse: Então aqueles dentre vós que podem, desçam com [igo] , e se houver alguma coisa errada neste homem, acusem-no.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 25, 6, 'E ele, tendo ficado entre eles mais de dez dias, desceu a Cesareia; e tendo se sentado no tribunal no [dia] seguinte, mandou que trouxessem a Paulo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 25, 7, 'E tendo ele vindo, os judeus que haviam descido de Jerusalém [o] rodearam, trazendo contra Paulo muitas e graves acusações, que não podiam provar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 25, 8, 'Ele, disse em sua defesa: Eu não pequei nem contra a Lei dos judeus, nem contra o Templo, nem contra César, em coisa alguma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 25, 9, 'Mas Festo, querendo agradar aos judeus, respondendo a Paulo, disse: Tu queres subir a Jerusalém e ser julgado sobre estas coisas diante de mim?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 25, 10, 'E Paulo disse: Eu estou diante do tribunal de César, onde eu tenho que ser julgado; a nenhum dos judeus eu fiz mal, assim como também tu sabes muito bem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 25, 11, 'Porque se eu fiz algum mal, ou cometi algo digno de morte, eu não recuso morrer; mas se nada há das coisas que este me acusam, ninguém pode me entregar a eles. Eu apelo a César.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 25, 12, 'Então Paulo, tendo conversado com o Conselho, respondeu: Tu apelaste a César; a César irás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 25, 13, 'E passados alguns dias, o Rei Agripa e Berenice vieram a Cesareia para saudar a Festo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 25, 14, 'E quando tinham ficado ali muitos dias, Festo contou ao rei os assuntos de Paulo, dizendo: Um certo homem foi deixado [aqui] preso por Félix;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 25, 15, 'Por causa do qual, estando eu em Jerusalém, os chefes dos sacerdotes e os anciãos dos judeus compareceram [a mim] , pedindo julgamento contra ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 25, 16, 'Aos quais eu respondi não ser costume dos romanos entregar a algum homem à morte, antes que o acusado tenha seus acusadores face a face, e tenha oportunidade para se defender da acusação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 25, 17, 'Portanto, tendo eles se reunido aqui, fazendo nenhum adiamento, no [dia] seguinte, estando eu sentado no tribunal, mandei trazer ao homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 25, 18, 'Do qual os acusadores estando [aqui] presentes, trouxeram como acusação nenhuma das coisas que eu suspeitava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 25, 19, 'Mas tinham contra ele algumas questões relativas às próprias crenças deles, e de um certo morto Jesus, o qual Paulo afirmava estar vivo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 25, 20, 'E eu, estando em duvida sobre [como] interrogar esta causa, disse, [perguntando] se ele queria ir a Jerusalém, e lá ser julgado sobre estas coisas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 25, 21, 'Porém Paulo, tendo apelado para ser guardado ao interrogatório do imperador, mandei que o guardassem, até que eu o enviasse a César.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 25, 22, 'E Agripa disse a Festo: Eu também queria ouvir a este homem.E ele disse: E amanhã tu o ouvirás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 25, 23, 'Então no dia seguinte, tendo vindo Agripa e Berenice, com muita pompa, e entrando no auditório com os comandantes e os homens mais importantes da cidade, trouxeram a Paulo por ordem de Festo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 25, 24, 'E Festo disse: Rei Agripa, e todos os homens que estais presentes [aqui] conosco, vós vedes este [homem] , a quem toda a multidão dos judeus, tanto em Jerusalém como aqui, tem apelado a mim, clamando que ele não deve mais viver.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 25, 25, 'Mas tendo eu achado nada que ele tenha feito que fosse digno de morte, e também tendo ele mesmo apelado ao imperador, eu decidi enviá-lo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 25, 26, 'Do qual eu não tenho coisa alguma certa para escrever ao [meu] senhor; por isso que eu o trouxe diante de vós; e principalmente diante de ti, rei Agripa, para que, sendo feita a investigação, eu tenha algo para escrever.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 25, 27, 'Porque não me parece razoável enviar a um prisioneiro, sem também informar as acusações contra ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 26, 1, 'E Agripa disse a Paulo: É permitido a ti falar por ti mesmo.Então Paulo, estendendo a mão, respondeu em sua defesa:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 26, 2, 'Eu me considero feliz, rei Agripa, de que diante de ti eu esteja hoje fazendo minha defesa de todas as coisas de que sou acusado pelos judeus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 26, 3, 'Principalmente [por] eu saber que tu sabes de todos os costumes e questões que há entre os judeus; por isso eu te rogo que tu me ouças com paciência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 26, 4, 'Ora, a minha vida é conhecida por todos os judeus, desde a [minha] juventude, que desde o princípio tem sido entre [os de] minha nação em Jerusalém;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 26, 5, 'Eles me conhecem desde o começo, se quiserem testemunhar, de que conforme a mais rigorosa divisão de nossa religião, eu vivi [como] fariseu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 26, 6, 'E agora, pela esperança da promessa que por Deus foi dada aos nossos pais, eu estou [aqui] sendo julgado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 26, 7, 'À qual nossas doze tribos, servindo continuamente [a Deus] de dia e de noite, esperam chegar; pela qual esperança, rei Agripa, eu sou acusado pelos judeus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 26, 8, 'Por que se julga como incrível entre vós que Deus ressuscite aos mortos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 26, 9, 'Eu realmente tinha pensado comigo mesmo, que contra o nome de Jesus eu tinha que fazer muitas oposições.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 26, 10, 'O que eu também fiz em Jerusalém; e tendo recebido autoridade dos chefes dos sacerdotes, eu pus em prisões a muitos dos santos; e quando eles eram mortos, eu [também] dava meu voto contra [eles] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 26, 11, 'E tendo lhes dado punição muitas vezes por todas as sinagogas, eu os forcei a blasfemarem. E estando extremamente enfurecido contra eles, até nas cidades estrangeiras eu os persegui;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 26, 12, 'Nas quais, indo eu até Damasco, com autoridade e comissão dos chefes dos sacerdotes;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 26, 13, 'Ao meio dia, vi no caminho, rei, uma luz do céu, que brilhava muito mais que o sol, e que encheu de claridade ao redor de mim e dos que iam comigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 26, 14, 'E todos nós, tendo caído ao chão, eu ouvi uma voz que falava a mim, e dizia em língua hebraica: Saulo, Saulo, por que me persegues? Duro é para ti dar coices contra os aguilhões.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 26, 15, 'E eu disse: Quem és, Senhor? E ele disse: Eu sou Jesus, a quem tu persegues.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 26, 16, 'Mas levanta-te, e fica de pé, porque para isto eu apareci a ti, para te predeterminar como trabalhador e testemunha, tanto das coisas que [já] tens visto, como das coisas que eu [ainda] aparecerei a ti;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 26, 17, 'Livrando-te d [este] povo, e [dos] gentios, aos quais agora eu te envio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 26, 18, 'Para abrir os olhos deles, e das trevas converterem à luz, e do poder de Satanás [converterem] a Deus; para que recebam perdão dos pecados, e herança entre os santificados pela fé em mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 26, 19, 'Portanto, rei Agripa, eu não fui desobediente à visão celestial.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 26, 20, 'Mas sim, primeiramente aos [que estavam] em Damasco e Jerusalém, e por toda a terra da Judeia, e aos gentios anunciei que se arrependessem, e se convertessem a Deus, fazendo obras dignas de arrependimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 26, 21, 'Por causa disto os judeus me pegaram no Templo, e procuravam [me] matar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 26, 22, 'Porém tendo eu obtido socorro de Deus, permaneço até o dia de hoje, dando testemunho tanto a pequenos como a grandes; não dizendo nada além dos que as [coisas] que os profetas e Moisés tinham dito que estavam para acontecer;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 26, 23, '[Isto é] , que o Cristo sofreria, e sendo o primeiro da ressurreição dos mortos, ia anunciar a luz a este povo e aos gentios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 26, 24, 'E tendo [Paulo] dito isto em [sua] defesa, Festo disse em alta voz: Tu estás louco, Paulo; as muitas escrituras te fizeram enlouquecer!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 26, 25, 'Mas ele [respondeu] : Eu não estou louco, excelentíssimo Festo; mas eu declaro palavras de verdade e de um são juízo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 26, 26, 'Porque o rei, a quem eu estou falando livremente, ele sabe [muito bem] destas coisas; porque eu não creio que nenhuma disto lhe seja oculto; por que isto não foi feito num canto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 26, 27, 'Rei Agripa, tu crês nos profetas? Eu sei que tu crês.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 26, 28, 'E Agripa disse a Paulo: Por pouco tu me convences a me tornar cristão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 26, 29, 'E Paulo disse: Meu desejo a Deus é que, por pouco ou por muito, não somente tu, mas todos os que estão me ouvindo hoje, tais vos tornásseis assim como eu sou, a não ser por estas correntes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 26, 30, 'E tendo ele dito isto, o rei se levantou, e [também] o governador, Berenice, e os que estavam sentados com eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 26, 31, 'E reunindo-se à parte, falavam uns aos outros, dizendo: Este homem nada faz [que seja] digno de morte ou de prisões.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 26, 32, 'E Agripa disse a Festo: Este homem podia ser solto, se ele não tivesse apelado a César.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 27, 1, 'E quando foi determinado que tínhamos que navegar para a Itália, entregaram a Paulo e alguns outros prisioneiros, a um centurião, por nome Júlio, do esquadrão imperial.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 27, 2, 'E embarcando [-nos] em um navio adramitino, estando a navegar pelos lugares [costeiros] da Ásia, nós partimos, estando conosco Aristarco, o macedônio de Tessalônica.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 27, 3, 'E no [dia] seguinte, chegamos a Sidom; e Júlio, tratando bem a Paulo, permitiu [-lhe] que fosse aos amigos, para [receber] cuidado [deles] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 27, 4, 'E tendo partido dali, nós fomos navegando abaixo do Chipre, porque os ventos estavam contrários.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 27, 5, 'E tendo passado ao longo do mar da Cilícia e Panfília, viemos a Mira em Lícia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 27, 6, 'E o centurião, tendo achado ali um navio de Alexandria, que estava navegando para a Itália, nos fez embarcar nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 27, 7, 'E indo navegando lentamente já por muitos dias, chegando com dificuldade em frente a Cnido, o vento, não nos permitindo [continuar por ali] ,navegamos abaixo de Creta, em frente a Salmone.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 27, 8, 'E tendo com dificuldade percorrido sua costa, chegamos a um certo lugar, chamado Bons Portos, perto do qual estava a cidade de Laseia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 27, 9, 'E tendo passado muito tempo, e sendo a navegação já perigosa, porque também já tinha passado o jejum, Paulo [os] exortava,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 27, 10, 'Dizendo-lhes: Homens, eu vejo que a navegação vai ser com violência e muito dano, não somente de carga e do navio, mas também de nossas vidas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 27, 11, 'Porém o centurião cria mais no capitão e no dono do navio do que no que Paulo dizia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 27, 12, 'E não sendo aquele porto adequado para passar o inverno, a maioria preferiu partir dali, para ver se podiam chegar a Fênix, que é um porto de Creta, voltada para o lado do vento sudoeste e noroeste, para ali passarem o inverno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 27, 13, 'E ao ventar brandamente ao sul, pareceu-lhes que eles já tinham o que queriam; e levantando a vela, foram por perto da costa de Creta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 27, 14, 'Mas não muito depois houve contra ela um vento violento, chamado Euroaquilão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 27, 15, 'E tendo o navio sido tomado por ele, e não podendo navegar contra o vento, nós deixamos sermos levados [por ele] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 27, 16, 'E correndo abaixo de uma pequena ilha, chamada Clauda, com dificuldade conseguimos manter o barquinho de reserva;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 27, 17, 'O qual, tendo sido levado para cima, usaram de suportes [para] reforçarem o navio; e temendo irem de encontro aos bancos de areia, eles baixaram as velas e [deixaram] ir à deriva.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 27, 18, 'E sendo muito afligidos pela tempestade, no [dia] seguinte jogaram a carga para fora [do navio] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 27, 19, 'E no terceiro [dia] , com as nossas próprias mãos jogamos fora os instrumentos do navio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 27, 20, 'E não aparecendo ainda o sol, nem estrelas havia muitos dias, e sendo afligidos por não pouca tempestade, desde então tínhamos perdido toda a esperança de sermos salvos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 27, 21, 'E havendo muito [tempo] que não havia o que comer, então Paulo, ficando de pé no meio deles, disse: Homens, vós devíeis ter dado atenção a mim, e não terdes partido de Creta, e [assim] evitar esta situação ruim e prejuízo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 27, 22, 'Mas agora eu vos exorto a terdes bom ânimo; porque haverá nenhuma perda de vida de vós, além [somente da perda] do navio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 27, 23, 'Porque esta mesma noite esteve comigo um anjo de Deus, a quem eu pertenço e a quem eu sirvo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 27, 24, 'Dizendo: Não temas, Paulo; é necessário que tu sejas apresentado a César; e eis que Deus tem te dado [a vida] a todos quantos navegam contigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 27, 25, 'Portanto, homens, tende bom ânimo; porque eu creio em Deus que assim será, conforme o que me foi dito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 27, 26, 'Mas é necessário que sejamos lançados a uma ilha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 27, 27, 'E quando veio a décima quarta noite, sendo lançados de um lado para o outro no [mar] Adriático, por volta da meia noite os marinheiros suspeitaram de que estavam se aproximando de alguma terra [firme] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 27, 28, 'E tendo lançado o prumo, acharam vinte braças; e passando um pouco mais adiante, voltando a lançar o prumo, acharam quinze braças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 27, 29, 'E temendo de irem de encontro a lugares rochosos, lançaram da popa quatro âncoras, desejando que o dia viesse [logo] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 27, 30, 'E [quando] os marinheiros estavam procurando fugir do navio, e baixando o barquinho de reserva ao mar, como que queriam largar as âncoras da proa,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 27, 31, 'Paulo disse ao centurião e aos soldados: Se estes não ficarem no navio, vós não podeis vos salvar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 27, 32, 'Então os soldados cortaram os cabos do barquinho de reserva, e o deixaram cair.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 27, 33, 'E até enquanto o dia estava vindo, Paulo exortava a todos que comessem alguma coisa, dizendo: Hoje já é o décimo quarto dia, em que estais esperando, continuando sem comer, nada tendo experimentado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 27, 34, 'Portanto eu vos exorto para que comais alguma coisa, pois é bom para vossa saúde; porque nenhum cabelo cairá de vossa cabeça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 27, 35, 'E tendo dito isto, e tomando o pão, ele agradeceu a Deus na presença de todos; e partindo [-o] , começou a comer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 27, 36, 'E todos, tendo ficado mais encorajados, também pegaram [algo] para comer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 27, 37, 'E éramos todos no navio duzentas e setenta e seis almas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 27, 38, 'E estando saciados de comer, eles tiraram peso do navio, lançando o trigo ao mar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 27, 39, 'E tendo vindo o dia, não reconheciam a terra; mas enxergaram uma enseada que tinha praia, na qual planejaram, se pudessem, levar o navio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 27, 40, 'E tendo levantado as âncoras, deixaram [-no] ir ao mar, soltando também as amarras dos lemes, e levantando a vela maior ao vento, foram de levando [-o] à praia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 27, 41, 'Mas tendo caído em um lugar onde dois mares se encontram, encalharam ali o navio; e fixa a proa, ficou imóvel, mas a popa estava se destruindo com a força das ondas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 27, 42, 'Então o conselho dos soldados foi de que matassem aos presos, para que nenhum [deles] fugisse a nado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 27, 43, 'Mas o centurião, querendo salvar a Paulo, impediu a intenção deles; e mandou que aqueles que pudessem nadar fossem os primeiros a se lançassem [ao mar] e chegassem à terra [firme] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 27, 44, 'E [depois] os demais, uns em tábuas, e outros em pedaços do navio. E assim aconteceu, que todos se salvaram em terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 28, 1, 'E tendo sobrevivido, então souberam que a ilha se chamava Malta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 28, 2, 'E os nativos demonstraram para conosco uma benevolência incomum; porque, tendo acendido uma fogueira, recolheram a nós todos, por causa da chuva que estava caindo, e por causa do frio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 28, 3, 'E tendo Paulo recolhido uma quantidade de gravetos, e pondo-os no fogo, saiu uma víbora do calor, e fixou [os dentes] na mão dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 28, 4, 'E quando os nativos vieram o animal pendurado na mão dele, disseram uns aos outros: Certamente este homem é assassino, ao qual, tendo sobrevivido do mar, a justiça não o deixa viver.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 28, 5, 'Porém, ele, tendo sacudido o animal ao fogo, sofreu nenhum mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 28, 6, 'E eles esperavam que ele fosse inchar, ou cair morto de repente. Mas tendo esperado muito, e vendo que nenhum incômodo tinha lhe sobrevindo, mudaram [de opinião] , e diziam que ele era um deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 28, 7, 'E perto daquele mesmo lugar o homem mais importante da ilha, por nome Públio, tinha algumas propriedades; o qual nos recebeu e nos hospedou por três dias gentilmente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 28, 8, 'E aconteceu que o pai de Públio estava de cama, doente de febres e disenteria; ao qual Paulo entrou, e tendo orado, pôs as mãos sobre ele, e o curou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 28, 9, 'Tendo então isto acontecido, também vieram a ele outros que tinham enfermidades, e foram curados;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 28, 10, 'Os quais nos honraram com muitas honras; e estando [nós] para navegar, [nos] entregaram as coisas necessárias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 28, 11, 'E três meses depois, nós partimos em um navio de Alexandria, que tinha passado o inverno na ilha; o qual tinha como símbolo os gêmeos Castor e Pólux.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 28, 12, 'E chegando a Siracusa, ficamos [ali] três dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 28, 13, 'De onde, tendo indo ao redor da costa, chegamos a Régio; e um dia depois, ventando ao sul, viemos o segundo dia a Putéoli.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 28, 14, 'Onde, tendo achado [alguns] irmãos, eles nos rogaram que ficássemos com eles por sete dias; e assim viemos a Roma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 28, 15, 'E os irmãos, ao ouvirem [notícias] sobre nós, desde lá nos saíram ao encontro até a praça de Ápio, e as três tavernas; e Paulo, tendo os visto, agradeceu a Deus, e tomou coragem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 28, 16, 'E quando chegamos a Roma, o centurião entregou os prisioneiros ao chefe da guarda, mas a Paulo foi permitido morar por si mesmo à parte, junto com o soldado que o guardava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 28, 17, 'E aconteceu que, três dias depois, Paulo chamou juntos os chefes dos judeus; e ao se reunirem, disse-lhes: Homens irmãos, tendo eu nada feito contra o povo, ou contra os costumes dos pais, [mesmo assim] eu vim preso desde Jerusalém, entregue em mãos dos romanos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 28, 18, 'Os quais, tendo me investigado, queriam [me] soltar, por não haver em mim nenhum crime de morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 28, 19, 'Mas os judeus, dizendo em contrário, eu fui forçado a apelar a César; [mas] não como que eu tenha que acusar a minha nação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 28, 20, 'Então por esta causa eu vos chamei até mim, para [vos] ver e falar; porque pela esperança de Israel eu estou agora preso nesta corrente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 28, 21, 'Mas eles lhe disseram: Nós nem recebemos cartas da Judeia relacionadas a ti, nem algum dos irmãos, tendo vindo aqui, tem nos informado ou falado de ti algum mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 28, 22, 'Mas nós queríamos ouvir de ti o que tu pensas; porque, quanto a esta seita, conhecemos que em todo lugar [há quem] fale contra ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 28, 23, 'E tendo eles lhe determinado um dia, muitos vieram até onde ele estava morando; aos quais ele declarava e dava testemunho do Reino de Deus; e procurava persuadi-los quanto a Jesus, tanto pela Lei de Moisés, como [pelos] profetas, desde a manhã até a tarde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 28, 24, 'E alguns criam nas coisas que ele dizia; mas outros não criam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 28, 25, 'E estando discordantes entre si, despediram-se, tendo Paulo disto [esta] palavra: O Espírito Santo corretamente falou a nossos pais por meio de Isaías o profeta,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 28, 26, 'Dizendo: Vai a este povo, e dize: De fato ouvireis, mas de maneira nenhuma entendereis; e de fato vereis, mas de maneira nenhuma enxergareis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 28, 27, 'Porque o coração deste povo está insensível, seus ouvidos ouvem com dificuldade, e seus olhos estão fechados; para que em maneira nenhuma vejam com os olhos, nem ouçam com os ouvidos, nem entendam com o coração, e se convertam, e eu os cure.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 28, 28, 'Portanto seja conhecido por vós que a salvação de Deus foi enviada aos gentios; e eles [a] ouvirão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 28, 29, 'E havendo ele dito isto, os judeus foram embora, havendo entre eles grande discussão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 28, 30, 'E Paulo ficou dois anos inteiros em sua própria casa alugada; e recebia a todos quantos vinham a ele;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 44, 'Atos', 'At', 28, 31, 'Pregando o Reino de Deus, e ensinando com ousadia a doutrina do Senhor Jesus Cristo, sem impedimento algum.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 1, 1, 'Paulo, servo de Jesus Cristo, chamado [para ser] apóstolo, separado para o evangelho de Deus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 1, 2, 'que antes havia prometido por meio dos seus profetas nas santas Escrituras,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 1, 3, 'acerca do seu Filho (que, quanto à carne, nasceu da descendência de Davi,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 1, 4, 'e declarado Filho de Deus em poder, segundo o Espírito de santidade, pela ressurreição dos mortos): Jesus Cristo, nosso Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 1, 5, 'Por ele recebemos graça e apostolado, para a obediência da fé entre todas as nações, por causa do seu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 1, 6, 'Entre elas sois também vós, chamados [para serdes] de Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 1, 7, 'A todos que estais em Roma, amados de Deus, e chamados de santos: convosco haja graça e paz da parte de Deus, nosso Pai, e do Senhor Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 1, 8, 'Em primeiro lugar, agradeço ao meu Deus por meio de Jesus Cristo, por todos vós, porque a vossa fé é anunciada no mundo todo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 1, 9, 'Pois Deus, a quem sirvo em meu espírito no evangelho do seu Filho, é minha testemunha de como sem cessar faço menção de vós,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 1, 10, 'rogando sempre em minhas orações, que agora, de alguma maneira, finalmente, tenha eu a oportunidade de, pela vontade de Deus, vir vos visitar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 1, 11, 'Pois eu desejo ver-vos, para compartilhar convosco algum dom espiritual, para que sejais fortalecidos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 1, 12, 'isto é, para eu ser consolado juntamente convosco pela fé mútua, tanto a vossa, como a minha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 1, 13, 'Porém, irmãos, não quero que ignoreis que muitas vezes pretendi vir à vossa presença (mas fui impedido até agora), a fim de que eu também tivesse algum fruto entre vós, como também entre os demais gentios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 1, 14, 'Eu sou devedor, tanto a gregos como a bárbaros, tanto a sábios como a não sábios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 1, 15, 'Portanto, quanto a mim, pronto estou para anunciar o evangelho também a vós, que estais em Roma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 1, 16, 'Porque não me envergonho do Evangelho de Cristo, pois é o poder de Deus para a salvação de todo aquele que crê, primeiramente do judeu, e também do grego.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 1, 17, 'Pois no Evangelho se revela a justiça de Deus de fé em fé; como está escrito: O justo viverá pela fé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 1, 18, 'Porque a ira de Deus se manifesta do céu contra toda irreverência e injustiça das pessoas que bloqueiam a verdade pela injustiça;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 1, 19, 'pois o que se pode conhecer de Deus é evidente a eles, porque Deus lhes manifestou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 1, 20, 'Pois as suas características invisíveis, inclusive o seu eterno poder e divindade, desde a criação do mundo são entendidas e claramente vistas por meio das coisas criadas, para que não tenham desculpa;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 1, 21, 'Porque, ainda que tenham conhecido Deus, não o glorificaram como Deus, nem foram gratos; em vez disso, perderam o bom senso em seus pensamentos, e seus tolos corações ficaram em trevas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 1, 22, 'Chamando a si mesmos de sábios, tornaram-se tolos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 1, 23, 'e trocaram a glória de Deus indestrutível por semelhança de imagem do ser humano destrutível, e de aves, de quadrúpedes, e de répteis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 1, 24, 'Por isso, Deus os entregou à imundície, nos desejos dos seus corações, para desonrarem os seus corpos entre si.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 1, 25, 'Trocaram a verdade de Deus pela mentira, e adoraram e serviram à criatura mais do que ao Criador, que é bendito eternamente, Amém!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 1, 26, 'Por isso, Deus os entregou a paixões infames. Pois até suas mulheres trocaram o hábito [sexual] natural pelo que era contra a natureza;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 1, 27, 'e também, de semelhante maneira, os machos abandonaram o hábito [sexual] natural com a mulher, e acenderam sua sensualidade uns com os outros, homens com homens, praticando indecência, e recebendo em si mesmos a devida retribuição pelo seu erro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 1, 28, 'E como recusaram reconhecer a Deus, [o mesmo] Deus os entregou a uma mente corrompida, para fazerem coisas impróprias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 1, 29, '[Assim, estão] cheios de toda injustiça, pecado sexual, malícia, ganância, maldade; estão repletos de inveja, homicídio, brigas, engano, malignidade;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 1, 30, 'são murmuradores, difamadores, e odeiam a Deus; são insolentes, soberbos, presunçosos, inventores de males, e desobedientes aos pais;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 1, 31, 'não têm entendimento, quebram acordos, são insensíveis, e recusam-se a perdoar ou a mostrar misericórdia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 1, 32, 'Apesar de conhecerem o juízo de Deus (de que os que fazem tais coisas merecem a morte), não somente as fazem, como também aprovam os que as praticam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 2, 1, 'Por isso, tu, que julgas, não tens desculpa; quem quer que sejas! Pois condenas a ti mesmo naquilo que julgas o outro, porque tu, que julgas, fazes as mesmas coisas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 2, 2, 'E sabemos que o julgamento de Deus é segundo a verdade sobre os que fazem tais coisas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 2, 3, 'E tu, humano, que julgas os que praticam tais coisas, ao fazê-las, pensas que escaparás do julgamento de Deus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 2, 4, 'Ou desprezas tu as riquezas de sua bondade, tolerância, e paciência, ignorando que é a bondade de Deus que te conduz ao arrependimento?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 2, 5, 'Mas, conforme a tua dureza e o teu coração que não se arrepende, tu ajuntas ira para ti no dia da ira e da manifestação do justo julgamento de Deus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 2, 6, 'que recompensará a cada um segundo as suas obras:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 2, 7, 'vida eterna aos que procuram glória, honra, e imortalidade, fazendo o bem com perseverança;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 2, 8, 'mas indignação e ira aos que agem com egoísmo, obedecendo à injustiça, e não à verdade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 2, 9, 'Haverá aflição e angústia a toda pessoa que pratica o mal, primeiramente ao judeu, e também ao grego;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 2, 10, 'porém, glória, honra, e paz, a todo aquele que pratica o bem, primeiramente ao judeu, e também ao grego;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 2, 11, 'porque com Deus não há acepção de pessoas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 2, 12, 'Pois todos os que sem Lei pecaram, sem Lei também perecerão; e todos os que pecaram sob a Lei, pela Lei serão julgados;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 2, 13, 'porque não são os que ouvem a Lei que são justos diante de Deus, mas sim, os que praticam a Lei que serão justificados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 2, 14, 'Pois quando os gentios, que não têm a Lei, praticam naturalmente as coisas que são da Lei, estes, ainda que não tenham a Lei, são lei para si mesmos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 2, 15, 'Eles mostram a obra da Lei escrita em seus corações, dando-lhes testemunho juntamente a sua consciência, e os pensamentos, ora acusando-os, ora defendendo-os.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 2, 16, 'Isso acontecerá no dia em que Deus julgará os segredos dos seres humanos por meio de Jesus Cristo, conforme o meu Evangelho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 2, 17, 'Eis que tu, que és chamado de judeu, e descansas confiando na Lei, e te orgulhas em Deus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 2, 18, 'conheces a vontade [dele] , e aprovas as melhores coisas, por seres instruído na lei;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 2, 19, 'e confias ser guia dos cegos, luz dos que estão nas trevas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 2, 20, 'instrutor dos tolos, professor das crianças, e que consideras a lei como a forma do conhecimento e da verdade;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 2, 21, 'tu, pois, que ensinas ao outro, não ensinas a ti mesmo? Tu que pregas que não se deve furtar, furtas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 2, 22, 'Tu que dizes que não se deve adulterar, adulteras? Tu que odeias os ídolos, profanas templos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 2, 23, 'Tu, que te orgulhas da Lei, pela transgressão da Lei desonras a Deus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 2, 24, 'porque, como está escrito: “O nome de Deus é blasfemado entre os gentios por vossa causa”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 2, 25, 'Pois a circuncisão tem proveito de fato se guardares a Lei; porém, se tu és transgressor da Lei, a tua circuncisão se torna incircuncisão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 2, 26, 'Ora, se o incircunciso obedecer às exigências da Lei, por acaso não será a sua incircuncisão considerada como circuncisão?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 2, 27, 'E se o que de natureza é incircunciso cumprir a Lei, ele julgará a ti, que mesmo com a norma escrita e a circuncisão és transgressor da Lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 2, 28, 'Pois judeu não é o de aparência externa, nem circuncisão é a na carne,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 2, 29, 'mas é judeu o que é no interior, e circuncisão é a de coração, no espírito, e não em uma norma escrita. Esse é elogiado não pelas pessoas, mas sim, por Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 3, 1, 'Qual, pois, é a vantagem do judeu? Ou qual é a utilidade da circuncisão?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 3, 2, 'Muita, em toda maneira. Pois, em primeiro lugar, as palavras de Deus lhes foram confiadas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 3, 3, 'Então, quê? Se alguns foram infiéis, a infidelidade deles anulará a fidelidade de Deus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 3, 4, 'De maneira nenhuma! Antes seja Deus verdadeiro, e todo ser humano mentiroso, como está escrito: “Para que sejas justificado em tuas palavras, e prevaleças quando julgares”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 3, 5, 'E, se a nossa injustiça evidencia a justiça de Deus, que diremos? Acaso Deus é injusto em impor [a sua] ira? (Falo na lógica humana).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 3, 6, 'De maneira nenhuma! De outro modo, como Deus julgará o mundo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 3, 7, 'Pois se, através da minha mentira, a verdade de Deus foi mais abundante para a sua glória, por que ainda sou também julgado como pecador?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 3, 8, 'E por que não [dizer] : “Façamos o mal, para que venha o bem”, como alguns nos caluniam, afirmando que nós dizemos isto? (A condenação destes é justa).')
